-- Shared runtime state mirrored from the compact baseline.
CREATE TABLE IF NOT EXISTS runtime_state (
    namespace VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    owner_id BIGINT NOT NULL,
    scope_key VARCHAR(160) COLLATE utf8mb4_bin NOT NULL DEFAULT '',
    session_id VARCHAR(160) COLLATE utf8mb4_bin NULL,
    state_key VARCHAR(128) COLLATE utf8mb4_bin NULL,
    revision BIGINT NOT NULL DEFAULT 0,
    state_code VARCHAR(32) COLLATE utf8mb4_bin NULL,
    current_ref VARCHAR(180) COLLATE utf8mb4_bin NULL,
    counter_value BIGINT NULL,
    provider VARCHAR(24) COLLATE utf8mb4_bin NULL,
    credential_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    actor_user_id BIGINT NULL,
    request_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    window_started_at DATETIME(6) NULL,
    window_ends_at DATETIME(6) NULL,
    payload_version SMALLINT NOT NULL DEFAULT 1,
    payload_json LONGTEXT NULL,
    created_at DATETIME(6) NULL,
    updated_at DATETIME(6) NULL DEFAULT (UTC_TIMESTAMP(6)),
    PRIMARY KEY (namespace,owner_id,scope_key),
    UNIQUE KEY uk_runtime_sdk_slot (namespace,owner_id,session_id,state_key),
    CONSTRAINT ck_runtime_owner CHECK (owner_id>=0),
    CONSTRAINT ck_runtime_revision CHECK (revision>=0),
    CONSTRAINT ck_runtime_counter CHECK (counter_value IS NULL OR counter_value>=0),
    CONSTRAINT ck_runtime_updated CHECK (namespace='RESEARCH_EXPORT_LIMIT' OR updated_at IS NOT NULL),
    CONSTRAINT ck_runtime_payload_version CHECK (payload_version>0),
    CONSTRAINT ck_runtime_payload CHECK (payload_json IS NULL OR (JSON_VALID(payload_json) AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT')),
    CONSTRAINT ck_runtime_sdk CHECK ((namespace='SDK_CHECKPOINT' AND owner_id>0 AND session_id IS NOT NULL AND state_key IS NOT NULL AND CHAR_LENGTH(scope_key)=64 AND revision>0 AND payload_version=1 AND payload_json IS NOT NULL) OR (namespace<>'SDK_CHECKPOINT' AND session_id IS NULL AND state_key IS NULL)),
    CONSTRAINT ck_runtime_model_control CHECK (namespace<>'MODEL_CONFIG_CONTROL' OR (owner_id=0 AND scope_key='GLOBAL' AND state_code IS NOT NULL AND state_code='READY' AND counter_value IS NOT NULL AND current_ref IS NOT NULL AND current_ref REGEXP '^(0|[1-9][0-9]{0,18})$' AND CAST(current_ref AS DECIMAL(20,0))<=counter_value AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL)),
    CONSTRAINT ck_runtime_key_revocation CHECK ((namespace='MODEL_KEY_REVOCATION' AND owner_id=0 AND state_code IS NOT NULL AND state_code='REVOKED' AND provider IS NOT NULL AND provider IN ('dashscope','deepseek','openai') AND credential_sha256 IS NOT NULL AND credential_sha256 REGEXP '^[a-f0-9]{64}$' AND scope_key=CONCAT(provider,':',credential_sha256) AND actor_user_id IS NOT NULL AND actor_user_id>0 AND request_id IS NOT NULL AND CHAR_LENGTH(request_id)>0 AND counter_value IS NOT NULL AND counter_value IN (0,1) AND created_at IS NOT NULL AND current_ref IS NULL AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL) OR (namespace<>'MODEL_KEY_REVOCATION' AND provider IS NULL AND credential_sha256 IS NULL AND actor_user_id IS NULL AND request_id IS NULL)),
    CONSTRAINT ck_runtime_research_export_limit CHECK (namespace<>'RESEARCH_EXPORT_LIMIT' OR (owner_id>0 AND scope_key='' AND revision=0 AND counter_value IS NOT NULL AND window_ends_at IS NOT NULL AND window_started_at IS NULL AND state_code IS NULL AND current_ref IS NULL AND payload_json IS NULL AND created_at IS NULL AND updated_at IS NULL)),
    CONSTRAINT ck_runtime_memory_preference CHECK (namespace<>'MEMORY_PREFERENCE' OR (owner_id>0 AND scope_key='' AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL AND created_at IS NULL AND payload_version=1 AND payload_json IS NOT NULL AND JSON_LENGTH(payload_json)=2 AND JSON_EXTRACT(payload_json,'$.readEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.readEnabled'))='BOOLEAN' AND JSON_EXTRACT(payload_json,'$.saveEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.saveEnabled'))='BOOLEAN')),
    KEY ix_runtime_state (namespace,state_code,owner_id)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
